describe('Popover Toggle', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display the popover when the button is clicked', () => {
        cy.get('.toggle-button').click(); // Replace with the actual selector for the button
        cy.get('.popover').should('be.visible'); // Replace with the actual selector for the popover
    });

    it('should hide the popover when the button is clicked again', () => {
        cy.get('.toggle-button').click(); // Open the popover
        cy.get('.toggle-button').click(); // Close the popover
        cy.get('.popover').should('not.be.visible'); // Check that the popover is hidden
    });
});
